// Site-wide translator. Instead of rewriting every component, we translate the
// rendered page: every English text node and UI attribute (placeholder, title,
// aria-label) is looked up in ar.json / ur.json and swapped in place. A
// MutationObserver keeps up as React re-renders, and switching back to English
// restores the original text. Numbers are kept: "3 of 8 reps" is looked up as
// "{0} of {1} reps" and the digits are put back.
//
// Dictionaries are generated by scripts/i18n/extract.mjs + translate.mjs.
// Mark anything that must never be translated with translate="no".

const ATTRS = ["placeholder", "title", "aria-label"];
const SKIP_TAGS = new Set(["SCRIPT", "STYLE", "TEXTAREA", "INPUT", "CODE", "PRE", "NOSCRIPT", "SVG"]);
const NUM = /\d+(?:[.,:]\d+)*/g;

const loaders = {
  ar: () => import("./ar.json").then((m) => m.default),
  ur: () => import("./ur.json").then((m) => m.default),
};
const cache = {};

let dict = null;           // active dictionary, null = English
let observer = null;
let queued = new Set();
let scheduled = false;
const textState = new WeakMap(); // Text node -> { orig, shown }
const attrState = new WeakMap(); // Element -> { [attr]: { orig, shown } }

export const RTL = new Set(["ar", "ur"]);

function lookup(original) {
  if (!dict) return null;
  const trimmed = original.replace(/\s+/g, " ").trim();
  if (!trimmed || !/[A-Za-z]/.test(trimmed)) return null;
  const nums = [];
  let i = 0;
  const key = trimmed.replace(NUM, (m) => { nums.push(m); return `{${i++}}`; });
  const hit = dict[key];
  if (!hit) return null;
  const filled = hit.replace(/\{(\d+)\}/g, (m, k) => (nums[+k] ?? m));
  const lead = original.match(/^\s*/)[0], trail = original.match(/\s*$/)[0];
  return lead + filled + trail;
}

function skipped(el) {
  for (let e = el; e; e = e.parentElement) {
    if (SKIP_TAGS.has(e.tagName) || e.isContentEditable) return true;
    if (e.getAttribute && (e.getAttribute("translate") === "no" || e.classList?.contains("notranslate"))) return true;
  }
  return false;
}

function doText(node) {
  const st = textState.get(node);
  // A changed value that isn't ours means React wrote new English text.
  const orig = st && node.nodeValue === st.shown ? st.orig : node.nodeValue;
  if (!dict) {
    if (st && node.nodeValue === st.shown) node.nodeValue = st.orig;
    textState.delete(node);
    return;
  }
  if (skipped(node.parentElement)) return;
  const out = lookup(orig);
  if (out == null) {
    if (st && node.nodeValue === st.shown) node.nodeValue = orig;
    textState.delete(node);
    return;
  }
  textState.set(node, { orig, shown: out });
  if (node.nodeValue !== out) node.nodeValue = out;
}

function doAttrs(el) {
  const states = attrState.get(el) || {};
  for (const a of ATTRS) {
    if (!el.hasAttribute(a)) continue;
    const cur = el.getAttribute(a);
    const st = states[a];
    const orig = st && cur === st.shown ? st.orig : cur;
    const out = dict && !skipped(el) ? lookup(orig) : null;
    if (out == null) {
      if (st && cur === st.shown) el.setAttribute(a, orig);
      delete states[a];
    } else {
      states[a] = { orig, shown: out };
      if (cur !== out) el.setAttribute(a, out);
    }
  }
  attrState.set(el, states);
}

function walk(root) {
  if (root.nodeType === Node.TEXT_NODE) { doText(root); return; }
  if (root.nodeType !== Node.ELEMENT_NODE) return;
  if (SKIP_TAGS.has(root.tagName)) { if (root.tagName === "INPUT" || root.tagName === "TEXTAREA") doAttrs(root); return; }
  doAttrs(root);
  const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
  let n;
  while ((n = w.nextNode())) {
    if (n.nodeType === Node.TEXT_NODE) doText(n);
    else doAttrs(n);
  }
}

function flush() {
  scheduled = false;
  const nodes = queued;
  queued = new Set();
  for (const n of nodes) if (n.isConnected) walk(n);
}
function queue(n) {
  queued.add(n);
  if (!scheduled) { scheduled = true; requestAnimationFrame(flush); }
}

function startObserver() {
  if (observer) return;
  observer = new MutationObserver((records) => {
    for (const r of records) {
      if (r.type === "characterData") {
        const st = textState.get(r.target);
        if (!st || r.target.nodeValue !== st.shown) queue(r.target);
      } else if (r.type === "attributes") {
        const st = attrState.get(r.target)?.[r.attributeName];
        if (!st || r.target.getAttribute(r.attributeName) !== st.shown) queue(r.target);
      } else {
        r.addedNodes.forEach(queue);
      }
    }
  });
  observer.observe(document.body, {
    subtree: true, childList: true, characterData: true,
    attributes: true, attributeFilter: ATTRS,
  });
}

/** Switch the whole page to `lang` ("en" | "ar" | "ur"). */
export async function applyLanguage(lang) {
  const html = document.documentElement;
  html.lang = lang;
  html.dir = RTL.has(lang) ? "rtl" : "ltr";
  if (lang === "en" || !loaders[lang]) {
    dict = null;
  } else {
    cache[lang] ||= await loaders[lang]();
    dict = cache[lang];
  }
  startObserver();
  walk(document.body);
  if (document.title) {
    html.dataset.titleEn ||= document.title;
    document.title = (dict && lookup(html.dataset.titleEn)) || html.dataset.titleEn;
  }
}

/** Translate one English string with the active dictionary (for alerts, speech, etc.). */
export function t(text) {
  return lookup(text) ?? text;
}

/** BCP-47 tag for speech synthesis / recognition. */
export const speechLang = (lang) => ({ ar: "ar-SA", ur: "ur-PK" })[lang] || "en-US";

/** Locale for dates and times in the current UI language. */
export const appLocale = () => ({ ar: "ar-AE", ur: "ur-PK" })[document.documentElement.lang] || "en-GB";
